   399  {
   400    int valid_isolate_count = 0;
   401    register FriBidiStrIndex i;
   402
   403    fribidi_assert (bidi_types);
   404
   405    for (i = 0; i < len; i++)
   406      {
   407        if (bidi_types[i] == FRIBIDI_TYPE_PDI)
   408          {
   409            /* Ignore if there is no matching isolate */
   410            if (valid_isolate_count>0)
   411              valid_isolate_count--;
   412          }
   413        else if (FRIBIDI_IS_ISOLATE(bidi_types[i]))
   414          valid_isolate_count++;
