   416          return FRIBIDI_IS_RTL (bidi_types[i]) ? FRIBIDI_PAR_RTL :
   417            FRIBIDI_PAR_LTR;
   418      }
   419
   420    return FRIBIDI_PAR_ON;
   421  }
