   467  static FriBidiPairingNode *
   468  pairing_nodes_sorted_merge(FriBidiPairingNode *nodes1,
   469                             FriBidiPairingNode *nodes2)
   470  {
   471    FriBidiPairingNode *res = NULL;
   472    if (!nodes1)
   473      return nodes2;
   474    if (!nodes2)
   475      return nodes1;
   476
   477    if (nodes1->open->pos < nodes2->open->pos)
   478      {
   479        res = nodes1;
   480        res->next = pairing_nodes_sorted_merge(nodes1->next, nodes2);
   481      }
   482    else
   483      {
   484        res = nodes2;
   485        res->next = pairing_nodes_sorted_merge(nodes1, nodes2->next);
   486      }
   487    return res;
   488  }
