   490  static void sort_pairing_nodes(FriBidiPairingNode **nodes)
   491  {
   492    FriBidiPairingNode *front, *back;
   493
   494    /* 0 or 1 node case */
   495    if (!*nodes || !(*nodes)->next)
   496      return;
   497
   498    pairing_nodes_front_back_split(*nodes, &front, &back);
   499    sort_pairing_nodes(&front);
   500    sort_pairing_nodes(&back);
   501    *nodes = pairing_nodes_sorted_merge(front, back);
   502  }
