   504  static void free_pairing_nodes(FriBidiPairingNode *nodes)
   505  {
   506    while (nodes)
   507      {
   508        FriBidiPairingNode *p = nodes;
   509        nodes = nodes->next;
   510        fribidi_free(p);
   511      }
